const { JSDOM, VirtualConsole } = require('/home/node/tmpdom/node_modules/jsdom');

const BASE = 'http://127.0.0.1:8765/';
const failures = [];

function wait(ms) { return new Promise(r => setTimeout(r, ms)); }
function check(name, cond, detail) {
  if (cond) console.log('PASS', name);
  else { failures.push(name + (detail ? ' :: ' + detail : '')); console.log('FAIL', name, detail || ''); }
}

async function load(page, setup) {
  const errors = [];
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => errors.push('jsdomError: ' + e.message));
  vc.on('error', (...args) => errors.push('console.error: ' + args.join(' ')));
  const dom = await JSDOM.fromURL(BASE + page, {
    runScripts: 'dangerously',
    resources: 'usable',
    pretendToBeVisual: true,
    virtualConsole: vc,
    beforeParse(window) {
      window.HTMLElement.prototype.scrollIntoView = function () {};
      window.addEventListener('error', e => errors.push('window error: ' + e.message));
      if (setup) setup(window);
    }
  });
  await new Promise(resolve => dom.window.addEventListener('load', resolve, { once: true }));
  await wait(150);
  return { dom, window: dom.window, document: dom.window.document, errors };
}

(async () => {
  // Home
  {
    const { window, document, errors } = await load('index.html');
    check('home: no console errors', errors.length === 0, errors.join(' | '));
    check('home: 6 featured cards', document.querySelectorAll('#featured-grid .course-card').length === 6, String(document.querySelectorAll('#featured-grid .course-card').length));
    check('home: 9 departments', document.querySelectorAll('#dept-grid .dept-card').length === 9, String(document.querySelectorAll('#dept-grid .dept-card').length));
    check('home: stats courses = 15', document.querySelector('#stat-courses').textContent === '15', document.querySelector('#stat-courses').textContent);
    check('home: nav has 4 links', document.querySelectorAll('#primary-nav a').length === 4);
    check('home: active nav home', document.querySelector('[data-nav="home"]').classList.contains('is-active'));
    window.close();
  }

  // Catalog
  {
    const { window, document, errors } = await load('catalog.html');
    check('catalog: no console errors', errors.length === 0, errors.join(' | '));
    check('catalog: 15 cards', document.querySelectorAll('#course-grid .course-card').length === 15, String(document.querySelectorAll('#course-grid .course-card').length));
    check('catalog: result count', document.querySelector('#results-count').textContent.includes('15'));
    const search = document.querySelector('#course-search');
    search.value = 'web';
    search.dispatchEvent(new window.Event('input', { bubbles: true }));
    await wait(30);
    check('catalog: search web -> 1 card', document.querySelectorAll('#course-grid .course-card').length === 1, String(document.querySelectorAll('#course-grid .course-card').length));
    check('catalog: search counts', document.querySelector('#results-count').textContent.includes('1'));
    document.querySelector('#filter-dept').value = 'Design';
    document.querySelector('#filter-dept').dispatchEvent(new window.Event('change', { bubbles: true }));
    await wait(30);
    check('catalog: combined filters empty', document.querySelectorAll('#course-grid .course-card').length === 0 && !document.querySelector('#empty-state').hidden);
    document.querySelector('#reset-filters').click();
    await wait(30);
    check('catalog: reset -> 15 cards', document.querySelectorAll('#course-grid .course-card').length === 15, String(document.querySelectorAll('#course-grid .course-card').length));
    document.querySelector('#filter-dept').value = 'Design';
    document.querySelector('#filter-dept').dispatchEvent(new window.Event('change', { bubbles: true }));
    await wait(30);
    check('catalog: Design -> 2 cards', document.querySelectorAll('#course-grid .course-card').length === 2, String(document.querySelectorAll('#course-grid .course-card').length));
    window.close();
  }

  // Catalog with dept URL
  {
    const { window, document, errors } = await load('catalog.html?dept=Psychology');
    check('catalog dept param: filters to Psychology', document.querySelectorAll('#course-grid .course-card').length === 2, String(document.querySelectorAll('#course-grid .course-card').length));
    check('catalog dept param: no errors', errors.length === 0, errors.join(' | '));
    window.close();
  }

  // Register: form validation, modal, confirm
  {
    const { window, document, errors } = await load('register.html?course=cs-340');
    check('register: no console errors', errors.length === 0, errors.join(' | '));
    check('register: course preselected', document.querySelector('#courseId').value === 'cs-340');
    check('register: preview shows course', document.querySelector('#course-preview').textContent.includes('Web Development'));
    check('register: empty table', document.querySelectorAll('#registrations-body tr.empty-row').length === 1);

    const form = document.querySelector('#registration-form');
    form.dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true }));
    await wait(40);
    check('register: empty submit shows errors', document.querySelectorAll('.field-error').length > 0 && document.querySelectorAll('[data-error-for]:not(:empty)').length >= 2, String(document.querySelectorAll('[data-error-for]:not(:empty)').length));

    document.querySelector('#fullName').value = 'Alex Morgan';
    document.querySelector('#studentId').value = '20261234';
    document.querySelector('#email').value = 'alex.morgan@university.edu';
    document.querySelector('#courseId').value = 'cs-340';
    document.querySelector('#courseId').dispatchEvent(new window.Event('change', { bubbles: true }));
    form.dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true }));
    await wait(50);
    check('register: confirmation modal opens', !!document.querySelector('.modal-overlay'));
    check('register: modal mentions course', document.querySelector('.modal-body').textContent.includes('CS 340'));

    document.querySelector('[data-modal-confirm]').click();
    await wait(350);
    check('register: modal closed', !document.querySelector('.modal-overlay'));
    check('register: one registered row', document.querySelectorAll('#registrations-body tr[data-reg-id]').length === 1, String(document.querySelectorAll('#registrations-body tr[data-reg-id]').length));
    check('register: success banner visible', !document.querySelector('#success-banner').hidden);
    check('register: nav badge shows 1', document.querySelector('.js-reg-count').textContent === '1' && !document.querySelector('.js-reg-count').hidden);
    check('register: stored in localStorage', JSON.parse(window.localStorage.getItem('uniflow.registrations')).length === 1);
    check('register: profile saved', !!window.localStorage.getItem('uniflow.profile'));

    const removeBtn = document.querySelector('.js-remove-registration');
    removeBtn.click();
    await wait(50);
    check('register: remove modal opens', !!document.querySelector('.modal-overlay'));
    document.querySelector('[data-modal-confirm]').click();
    await wait(350);
    check('register: row removed', document.querySelectorAll('#registrations-body tr[data-reg-id]').length === 0);
    check('register: empty state after remove', !!document.querySelector('#registrations-body tr.empty-row'));
    check('register: no errors after interactions', errors.length === 0, errors.join(' | '));
    window.close();
  }

  // Profile seeded
  {
    const seedRegs = [{ id: 'r1', courseId: 'cs-340', semester: 'Fall 2026', studentName: 'Alex Morgan', studentId: '20261234', email: 'alex.morgan@university.edu', createdAt: new Date().toISOString() }];
    const seedProfile = { name: 'Alex Morgan', studentId: '20261234', email: 'alex.morgan@university.edu', program: 'Computer Science', year: 'Second year' };
    const { window, document, errors } = await load('profile.html', w => {
      w.localStorage.setItem('uniflow.registrations', JSON.stringify(seedRegs));
      w.localStorage.setItem('uniflow.profile', JSON.stringify(seedProfile));
    });
    check('profile: no console errors', errors.length === 0, errors.join(' | '));
    check('profile: name shown', document.querySelector('#profile-name').textContent === 'Alex Morgan');
    check('profile: stats count 1', document.querySelector('#stat-my-courses').textContent === '1');
    check('profile: credits count 3', document.querySelector('#stat-my-credits').textContent === '3');
    check('profile: one row', document.querySelectorAll('#profile-registrations-body tr[data-reg-id]').length === 1);
    document.querySelector('#edit-profile-btn').click();
    await wait(50);
    check('profile: edit form opens', !document.querySelector('#profile-form').hidden);
    document.querySelector('#profileProgram').value = 'Design';
    document.querySelector('#profile-form').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true }));
    await wait(50);
    check('profile: form closes after save', document.querySelector('#profile-form').hidden);
    check('profile: program updated', document.querySelector('#profile-program').textContent === 'Design', document.querySelector('#profile-program').textContent);
    check('profile: saved program', JSON.parse(window.localStorage.getItem('uniflow.profile')).program === 'Design');
    check('profile: no errors after edit', errors.length === 0, errors.join(' | '));
    window.close();
  }

  // Profile empty
  {
    const { window, document, errors } = await load('profile.html');
    check('profile empty: guest name', document.querySelector('#profile-name').textContent === 'Guest Student');
    check('profile empty: empty table row', !!document.querySelector('#profile-registrations-body tr.empty-row'));
    check('profile empty: no errors', errors.length === 0, errors.join(' | '));
    window.close();
  }

  console.log('\n' + (failures.length ? 'FAILURES:\n' + failures.join('\n') : 'ALL TESTS PASSED'));
  process.exit(failures.length ? 1 : 0);
})().catch(err => { console.error(err); process.exit(1); });
